SELECT category, COUNT(DISTINCT supplier_id) AS supplier_count
FROM supplier
GROUP BY category;

SELECT business_unit, COUNT(project_code) AS project_count
FROM project
GROUP BY business_unit;

SELECT business_unit, SUM(contract_amt) AS contract_amt_total
FROM project
GROUP BY business_unit;

SELECT ms_status, COUNT(milestone_id) AS 节点数量
FROM milestone
GROUP BY ms_status;

SELECT workshop, COUNT(work_order_id) AS 工单数量
FROM work_order
GROUP BY workshop;

SELECT customer_name
FROM sales_order
WHERE job_no IN ('WO-3001', 'WO-3004', 'WO-3009');
